// Daily rotation: a deterministic index from the local calendar date so the
// puzzle changes at local midnight and is identical for everyone that day.
const EPOCH = Date.UTC(2024, 0, 1); // 2024-01-01
const DAY_MS = 86400000;

export function dayIndexFor(date = new Date()) {
  // Use the local Y/M/D (not UTC) so the change happens at the player's midnight.
  const local = Date.UTC(date.getFullYear(), date.getMonth(), date.getDate());
  return Math.floor((local - EPOCH) / DAY_MS);
}

export function getDailyPuzzle(date = new Date()) {
  const idx = ((dayIndexFor(date) % PUZZLES.length) + PUZZLES.length) % PUZZLES.length;
  return { puzzle: PUZZLES[idx], index: idx };
}
